CREATE POLICY "Staff upload website photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'website-photos' AND private.is_staff(auth.uid()) AND name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Staff preview website photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'website-photos' AND private.is_staff(auth.uid()));
CREATE POLICY "Published website photos only" ON storage.objects FOR SELECT TO anon USING (bucket_id = 'website-photos' AND EXISTS (SELECT 1 FROM public.website_content c WHERE c.value = '/api/public/website-photo?path=' || storage.objects.name));
CREATE OR REPLACE FUNCTION public.validate_website_value() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.key)>120 OR length(NEW.value)>6000 THEN RAISE EXCEPTION 'Content is too long'; END IF; IF NEW.key IN ('contact.phone','contact.snack_phone') AND NEW.value !~ '^\+?[0-9 ()-]{10,25}$' THEN RAISE EXCEPTION 'Enter a valid phone number'; END IF; IF NEW.key LIKE '%.photo' OR NEW.key IN ('home.hero','home.how','home.league') THEN IF NEW.value <> '' AND NEW.value !~ '^https://' AND NEW.value !~ '^/__l5e/assets-v1/' AND NEW.value !~ '^/api/public/website-photo\?path=[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$' THEN RAISE EXCEPTION 'Use a secure image link or uploaded website photo'; END IF; END IF; RETURN NEW; END $$;